import json
import os
from typing import Iterator, Optional, Union
import boto3

class InputReader:
    def __init__(self, source: Union[str, dict], fail_on_missing: bool = False):
        self.fail_on_missing = fail_on_missing
        if isinstance(source, str):
            self.source = source
        elif isinstance(source, dict):
            self.source = source
        else:
            raise ValueError("Source must be a string or a dictionary.")

    def _read_file(self, filepath: str) -> Iterator[str]:
        if not os.path.exists(filepath):
            if self.fail_on_missing:
                raise FileNotFoundError(f"File not found: {filepath}")
            else:
                return iter([])
        with open(filepath, 'r') as file:
            for line in file:
                yield line

    def _read_bucket(self, bucket_name: str, key: str) -> Iterator[str]:
        s3 = boto3.client('s3')
        try:
            obj = s3.get_object(Bucket=bucket_name, Key=key)
            for line in obj['Body'].iter_lines():
                yield line.decode('utf-8')
        except s3.exceptions.NoSuchKey:
            if self.fail_on_missing:
                raise FileNotFoundError(f"Object not found in bucket: {bucket_name}/{key}")
            else:
                return iter([])

    def __iter__(self) -> Iterator[str]:
        if isinstance(self.source, str):
            if self.source.startswith("s3://"):
                _, bucket_name, key = self.source.split('/', 2)
                return self._read_bucket(bucket_name, key)
            else:
                return self._read_file(self.source)
        elif isinstance(self.source, dict):
            if 'bucket' in self.source and 'key' in self.source:
                return self._read_bucket(self.source['bucket'], self.source['key'])
            elif 'file' in self.source:
                return self._read_file(self.source['file'])
            else:
                raise ValueError("Invalid JSON source format.")
        else:
            raise ValueError("Invalid source type.")

    @classmethod
    def from_json(cls, json_str: str, fail_on_missing: bool = False) -> 'InputReader':
        source = json.loads(json_str)
        return cls(source, fail_on_missing)

    def to_json(self) -> str:
        return json.dumps(self.source)

